/* Parseo y normalización; admite string u objeto */
const topic = $json.topic ?? null;
const raw = $json.message ?? $json.payload ?? $json;
let obj;
try {
  obj = (typeof raw === 'string') ? JSON.parse(raw) : raw;
} catch (e) {
  return [{ json: { __parse_error: e.message, __raw: raw, __topic: topic } }];
}

const out = {
  device_id: obj.deviceId ?? obj.device_id ?? 'unknown',
  distance_cm: Number(obj.distance_cm),
  angle_deg: Number(obj.angle_deg),
  raw_us: Number(obj.raw_us),
  correlation_id: obj.correlationId ?? obj.correlation_id ?? null,
  __topic: topic,
  __raw: typeof raw === 'string' ? raw : JSON.stringify(raw)
};

return [{ json: out }];

/* Construye fila de error para tabla ultrasonic_errors */
let reason = '';
if ($json.__parse_error) {
  reason = `JSON parse error: ${$json.__parse_error}`;
} else {
  const parts = [];
  if (!($json.device_id && String($json.device_id).length)) parts.push('device_id missing');
  if (!(Number.isFinite($json.distance_cm) && $json.distance_cm > 0)) parts.push('distance_cm invalid');
  if (!(Number.isFinite($json.angle_deg) && $json.angle_deg >= 0)) parts.push('angle_deg invalid');
  if (!Number.isFinite($json.raw_us)) parts.push('raw_us invalid');
  reason = parts.join(', ');
}
return [{ json: {
  topic: $json.__topic ?? null,
  raw_payload: $json.__raw ? String($json.__raw) : JSON.stringify($json),
  error_msg: reason
}}];
